const body = $input.first().json?.body ?? $input.first().json ?? {};
const post_id = body.post_id ?? null;
const slug = String(body.slug ?? '').trim();
const title = String(body.title ?? '').trim().slice(0, 300);
const excerpt = String(body.excerpt ?? '').trim().slice(0, 500);
const media_url = typeof body.media_url === 'string' && body.media_url.trim() ? body.media_url.trim() : null;
const media_type = body.media_type === 'video' ? 'video' : 'image';
const link = typeof body.link === 'string' && body.link.trim() ? body.link.trim() : null;
const tiktokToken = String($env.TIKTOK_ACCESS_TOKEN ?? $env.TIKTOK_USER_ACCESS_TOKEN ?? '').trim();
if (!tiktokToken) {
  return [{ json: { ok: false, error: 'tiktok_not_configured', post_id, message: 'Set TIKTOK_ACCESS_TOKEN in n8n env' } }];
}
const caption = [title, excerpt, link].filter(Boolean).join('\n\n').slice(0, 2200);
return [{ json: { post_id, slug, title, excerpt, media_url, media_type, link, caption, tiktok_token: tiktokToken } }];
